def get_current_time(clock_header: Optional[str]) -> str:
    if clock_header:
        try:
            datetime.fromisoformat(clock_header.replace('Z', '+00:00'))
            return clock_header
        except ValueError:
            raise HTTPException(status_code=400, detail="Invalid X-Test-Clock format")
    return datetime.now(timezone.utc).isoformat()

def is_business_hours(dt: datetime) -> bool:
    dt_local = dt.astimezone(WARSAW)
    return dt_local.weekday() < 5 and 8 <= dt_local.hour < 16

def add_business_hours(start_dt: datetime, hours: float) -> datetime:
    dt = start_dt.astimezone(WARSAW)
    remaining_seconds = hours * 3600

    while remaining_seconds > 0:
        if dt.weekday() >= 5:
            days_ahead = 7 - dt.weekday()
            dt = dt.replace(hour=8, minute=0, second=0, microsecond=0) + timedelta(days=days_ahead)
            continue
        if dt.hour < 8:
            dt = dt.replace(hour=8, minute=0, second=0, microsecond=0)
            continue
        if dt.hour >= 16:
            days_ahead = 1 if dt.weekday() < 4 else 3
            dt = dt.replace(hour=8, minute=0, second=0, microsecond=0) + timedelta(days=days_ahead)
            continue

        end_of_day = dt.replace(hour=16, minute=0, second=0, microsecond=0)
        seconds_to_eod = (end_of_day - dt).total_seconds()

        if remaining_seconds <= seconds_to_eod:
            dt += timedelta(seconds=remaining_seconds)
            remaining_seconds = 0
        else:
            dt = end_of_day
            remaining_seconds -= seconds_to_eod

    return dt.astimezone(timezone.utc)

def calculate_sla(created_at: str, priority: str) -> dict:
    dt_created = datetime.fromisoformat(created_at.replace('Z', '+00:00'))
    sla_matrix = {
        "P1": (0.25, 4.0),
        "P2": (1.0, 8.0),
        "P3": (4.0, 24.0),
        "P4": (8.0, 72.0)
    }
    ack_hrs, resolve_hrs = sla_matrix.get(priority, (8.0, 72.0))
    ack_due = add_business_hours(dt_created, ack_hrs)
    resolve_due = add_business_hours(dt_created, resolve_hrs)
    close_due = resolve_due + timedelta(days=7) 
    return {
        "ack_due_at": ack_due.isoformat().replace('+00:00', 'Z'),
        "resolve_due_at": resolve_due.isoformat().replace('+00:00', 'Z'),
        "close_due_at": close_due.isoformat().replace('+00:00', 'Z')
    }

# --- L2 DORA HELPERS & MATH ---
def parse_iso(dt_str: str) -> datetime:
    if dt_str.endswith("Z"):
        dt_str = dt_str[:-1] + "+00:00"
    return datetime.fromisoformat(dt_str).astimezone(timezone.utc)

def round_half_up(val: float, decimals: int = 0):
    if val is None:
        return None
    d = Decimal(str(val))
    if decimals == 0:
        return int(d.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    else:
        q = Decimal('10') ** -decimals
        return float(d.quantize(q, rounding=ROUND_HALF_UP))

def compute_median(values: List[float]) -> Optional[int]:
    if not values:
        return None
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        med = float(s[n // 2])
    else:
        med = float(s[n // 2 - 1] + s[n // 2]) / 2.0
    return round_half_up(med, 0)

