@app.post("/tickets", status_code=201)
def create_ticket(ticket: TicketCreate, x_test_clock: Optional[str] = Header(None, alias="X-Test-Clock")):
    ticket_id = str(uuid.uuid4())
    created_at = get_current_time(x_test_clock)
    matrix = {
        (1, 1): "P1", (1, 2): "P2", (1, 3): "P3",
        (2, 1): "P2", (2, 2): "P3", (2, 3): "P4",
        (3, 1): "P3", (3, 2): "P4", (3, 3): "P4",
    }
    base_priority = matrix.get((ticket.impact, ticket.urgency), "P4")
    final_priority = base_priority
    if ticket.reporter.vip and base_priority in ["P3", "P4"]:
        final_priority = "P2"
        
    new_ticket = {
        "id": ticket_id,
        "title": ticket.title,
        "state": "new",
        "priority": final_priority,
        "created_at": created_at,
        "reporter": ticket.reporter.model_dump(),
        "sla": calculate_sla(created_at, final_priority)
    }
    tickets_db[ticket_id] = new_ticket
    return new_ticket

