@app.post("/tickets/{ticket_id}/{action}", status_code=200)
def transition_ticket(ticket_id: str, action: str, x_test_clock: Optional[str] = Header(None, alias="X-Test-Clock")):
    if ticket_id not in tickets_db:
        raise HTTPException(status_code=404, detail="Not Found")
    
    ticket = tickets_db[ticket_id]
    current_state = ticket["state"]
    current_time = get_current_time(x_test_clock)
    
    if action == "ack":
        if current_state != "new": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "acknowledged"
        ticket["acknowledged_at"] = current_time
    elif action == "start":
        if current_state != "acknowledged": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "in_progress"
        ticket["started_at"] = current_time
    elif action == "resolve":
        if current_state != "in_progress": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "resolved"
        ticket["resolved_at"] = current_time
    elif action == "close":
        if current_state != "resolved": raise HTTPException(status_code=409, detail="Conflict")
        ticket["state"] = "closed"
        ticket["closed_at"] = current_time
    elif action == "reopen":
        if current_state == "closed": raise HTTPException(status_code=409, detail="Ticket is immutable (C2)")
        if current_state != "resolved": raise HTTPException(status_code=409, detail="Conflict")
        resolved_at = datetime.fromisoformat(ticket["resolved_at"].replace('Z', '+00:00'))
        now = datetime.fromisoformat(current_time.replace('Z', '+00:00'))
        if (now - resolved_at).total_seconds() > 7 * 86400:
            raise HTTPException(status_code=409, detail="Reopen window expired")
        ticket["state"] = "in_progress"
    else:
        raise HTTPException(status_code=404, detail="Invalid action")
    return ticket

