@app.get("/dora/ticket-events")
def get_ticket_events():
    events = []
    phase_to_state = {"created": "new", "acknowledged": "acknowledged", "resolved": "resolved", "closed": "closed"}
    for tid, ticket in tickets_db.items():
        priority = ticket.get("priority", "P4")
        timestamps = [
            ("created", ticket.get("created_at")),
            ("acknowledged", ticket.get("acknowledged_at")),
            ("resolved", ticket.get("resolved_at")),
            ("closed", ticket.get("closed_at"))
        ]
        for phase, ts in timestamps:
            if ts:
                events.append({
                    "ticket_id": tid,
                    "at": ts,
                    "phase": phase,
                    "priority": priority,
                    "state": phase_to_state[phase]
                })
    events.sort(key=lambda x: (x["at"], x["ticket_id"]))
    return events

@app.post("/dora/metrics")
def calculate_dora_metrics(payload: Dict[str, Any]):
    if not isinstance(payload, dict) or "window" not in payload or not isinstance(payload["window"], dict):
        raise HTTPException(status_code=422, detail="Missing or invalid window")
    win = payload["window"]
    if "from" not in win or "to" not in win:
        raise HTTPException(status_code=422, detail="Window missing from/to")
    try:
        dt_from = parse_iso(win["from"])
        dt_to = parse_iso(win["to"])
    except Exception:
        raise HTTPException(status_code=422, detail="Invalid window timestamp")
    if dt_to <= dt_from:
        raise HTTPException(status_code=422, detail="Window to <= from")
    if "events" not in payload or not isinstance(payload["events"], list):
        raise HTTPException(status_code=422, detail="Missing or invalid events array")

    raw_events = payload["events"]

    # R-05 Deduplication by event_id
    seen_ids = set()
    events = []
    for ev in raw_events:
        eid = ev.get("event_id") or (ev.get("type"), ev.get("sha"), ev.get("at"))
        if eid not in seen_ids:
            seen_ids.add(eid)
            events.append(ev)

    # Well-formedness checks (R-06 & section 1)
    known_shas = {ev["sha"] for ev in events if ev.get("type") == "commit" and "sha" in ev}
    known_incidents = {ev["incident_id"] for ev in events if ev.get("type") == "incident" and "incident_id" in ev}
    known_deployments = {ev["deployment_id"] for ev in events if ev.get("type") == "deployment" and "deployment_id" in ev}

    for ev in events:
        if ev.get("type") == "commit":
            reverts = ev.get("reverts")
            change_id = ev.get("change_id")
            if reverts is not None:
                if change_id is not None or reverts not in known_shas:
                    raise HTTPException(status_code=422, detail=f"Malformed revert commit {ev}")
            else:
                if change_id is None:
                    raise HTTPException(status_code=422, detail=f"Malformed commit missing change_id {ev}")
        elif ev.get("type") == "deployment":
            for c_sha in ev.get("commits", []):
                if c_sha not in known_shas:
                    raise HTTPException(status_code=422, detail=f"Deployment commit {c_sha} unknown")
            caused_by = ev.get("caused_by")
            if caused_by is not None and caused_by not in known_incidents:
                raise HTTPException(status_code=422, detail=f"Deployment caused_by {caused_by} unknown")
        elif ev.get("type") == "incident":
            for d_id in ev.get("deployments", []):
                if d_id not in known_deployments:
                    raise HTTPException(status_code=422, detail=f"Incident deployment {d_id} unknown")

    commits_by_sha = {ev["sha"]: ev for ev in events if ev.get("type") == "commit"}

    # R-06 Change Identity
    change_id_map = {}
    revert_chains_collapsed = 0
    for sha, c_ev in commits_by_sha.items():
        if c_ev.get("reverts"):
            revert_chains_collapsed += 1
            curr = c_ev
            visited = {sha}
            while curr.get("reverts"):
                rev_sha = curr.get("reverts")
                if rev_sha in visited or rev_sha not in commits_by_sha:
                    break
                visited.add(rev_sha)
                curr = commits_by_sha[rev_sha]
            change_id_map[sha] = curr.get("change_id")
        else:
            change_id_map[sha] = c_ev.get("change_id")

    all_changes = set(cid for cid in change_id_map.values() if cid is not None)

    # R-07 First commit instant
    change_first_commit_at = {}
    for sha, c_ev in commits_by_sha.items():
        cid = change_id_map.get(sha)
        if cid:
            c_at = parse_iso(c_ev["at"])
            if cid not in change_first_commit_at or c_at < change_first_commit_at[cid]:
                change_first_commit_at[cid] = c_at

    # R-01 & R-02 Production deployments in window
    deployments_in_window = []
    deployments_without_commits = 0
    for ev in events:
        if ev.get("type") == "deployment" and ev.get("environment") == "production":
            d_at = parse_iso(ev["at"])
            if dt_from <= d_at < dt_to:
                deployments_in_window.append(ev)
                if not ev.get("commits"):
                    deployments_without_commits += 1

    # E3 commits_never_on_main
    commits_never_on_main_shas = set()
    for d in deployments_in_window:
        for sha in d.get("commits", []):
            if sha in commits_by_sha and commits_by_sha[sha].get("branch") != "main":
                commits_never_on_main_shas.add(sha)

    # R-08 Lead time pairs
    deployed_shas_seen = set()
    lead_time_pairs_values = []
    negative_lead_time_pairs = 0
    deployments_in_window_sorted = sorted(deployments_in_window, key=lambda x: parse_iso(x["at"]))

    for d in deployments_in_window_sorted:
        d_at = parse_iso(d["at"])
        if d.get("outcome") == "success":
            for sha in d.get("commits", []):
                if sha not in deployed_shas_seen:
                    deployed_shas_seen.add(sha)
                    if sha in commits_by_sha:
                        c_at = parse_iso(commits_by_sha[sha]["at"])
                        lt_sec = (d_at - c_at).total_seconds()
                        if lt_sec < 0:
                            negative_lead_time_pairs += 1
                            lt_sec = 0.0
                        lead_time_pairs_values.append(lt_sec)

    change_lead_time_seconds_p50 = compute_median(lead_time_pairs_values)

    # R-11 Deployment frequency
    window_days = (dt_to - dt_from).total_seconds() / 86400.0
    total_deployments = len(deployments_in_window)
    df_per_day = round_half_up(total_deployments / window_days, 6) if window_days > 0 else 0.0

    successful_deployments = [d for d in deployments_in_window if d.get("outcome") == "success"]
    failed_deployments = [d for d in deployments_in_window if d.get("outcome") == "failure"]

    # R-14 CFR & R-15 DRR
    cfr = round_half_up(len(failed_deployments) / total_deployments, 6) if total_deployments > 0 else None
    rework_deps = [d for d in deployments_in_window if d.get("unplanned") is True and d.get("caused_by") is not None]
    drr = round_half_up(len(rework_deps) / total_deployments, 6) if total_deployments > 0 else None

    # R-12 & R-13 Incidents & Recovery
    incidents_by_id = {}
    for ev in events:
        if ev.get("type") == "incident":
            iid = ev["incident_id"]
            if iid not in incidents_by_id:
                incidents_by_id[iid] = {"opened": None, "resolved": None, "deployments": []}
            p = ev.get("phase")
            if p == "opened":
                incidents_by_id[iid]["opened"] = parse_iso(ev["at"])
                incidents_by_id[iid]["deployments"] = ev.get("deployments", [])
            elif p == "resolved":
                incidents_by_id[iid]["resolved"] = parse_iso(ev["at"])

    # E6 overlapping
    inc_list = list(incidents_by_id.items())
    overlapping_pairs = 0
    for i in range(len(inc_list)):
        o1 = inc_list[i][1]["opened"]
        if o1 is None: continue
        r1 = inc_list[i][1]["resolved"] if inc_list[i][1]["resolved"] is not None else dt_to
        for j in range(i + 1, len(inc_list)):
            o2 = inc_list[j][1]["opened"]
            if o2 is None: continue
            r2 = inc_list[j][1]["resolved"] if inc_list[j][1]["resolved"] is not None else dt_to
            if o1 < r2 and o2 < r1:
                overlapping_pairs += 1

    recovery_times = []
    recovered_failures_count = 0
    open_failures_count = 0

    for fd in failed_deployments:
        dep_id = fd["deployment_id"]
        d_at = parse_iso(fd["at"])
        candidates = []
        for iid, inc in incidents_by_id.items():
            if dep_id in inc["deployments"] and inc["opened"] is not None:
                candidates.append((inc["opened"], iid, inc))
        if candidates:
            candidates.sort(key=lambda x: (x[0], x[1]))
            covering_inc = candidates[0][2]
            if covering_inc["resolved"] is not None:
                recovered_failures_count += 1
                rec_sec = max(0.0, (covering_inc["resolved"] - d_at).total_seconds())
                recovery_times.append(rec_sec)
            else:
                open_failures_count += 1
        else:
            open_failures_count += 1

    fdrt_p50 = compute_median(recovery_times)

    # R-16 & R-17 Ground truth
    changes_delivered_map = {}
    for d in deployments_in_window_sorted:
        if d.get("outcome") == "success":
            d_at = parse_iso(d["at"])
            for sha in d.get("commits", []):
                cid = change_id_map.get(sha)
                if cid and (cid not in changes_delivered_map or d_at < changes_delivered_map[cid]):
                    changes_delivered_map[cid] = d_at

    true_lead_times = [
        max(0.0, (first_dep_at - change_first_commit_at[cid]).total_seconds())
        for cid, first_dep_at in changes_delivered_map.items()
    ]
    true_clt_p50 = compute_median(true_lead_times)

    return {
        "spec_version": "1.0.0",
        "window": {"from": win["from"], "to": win["to"]},
        "deployment_frequency_per_day": df_per_day,
        "change_lead_time_seconds_p50": change_lead_time_seconds_p50,
        "failed_deployment_recovery_time_seconds_p50": fdrt_p50,
        "change_fail_rate": cfr,
        "deployment_rework_rate": drr,
        "counts": {
            "deployments": total_deployments,
            "successful_deployments": len(successful_deployments),
            "failed_deployments": len(failed_deployments),
            "recovered_failures": recovered_failures_count,
            "open_failures": open_failures_count,
            "rework_deployments": len(rework_deps),
            "lead_time_pairs": len(lead_time_pairs_values),
            "changes": len(all_changes)
        },
        "anomalies": {
            "negative_lead_time_pairs": negative_lead_time_pairs,
            "deployments_without_commits": deployments_without_commits,
            "commits_never_on_main": len(commits_never_on_main_shas),
            "revert_chains_collapsed": revert_chains_collapsed,
            "overlapping_incident_pairs": overlapping_pairs
        },
        "ground_truth": {
            "changes_delivered": len(changes_delivered_map),
            "true_change_lead_time_seconds_p50": true_clt_p50
        }
    }